/**
 * Clean and deduplicate labels stably with case-insensitivity.
 *
 * @param {any} input
 * @returns {string[]}
 */
function normalizeLabels(input) {
  if (!Array.isArray(input)) {
    return [];
  }

  const seen = new Set();
  const result = [];

  for (let i = 0; i < input.length; i++) {
    const item = input[i];
    if (typeof item !== 'string') {
      continue;
    }

    const trimmed = item.trim();
    if (trimmed.length === 0) {
      continue;
    }

    const key = trimmed.toLowerCase();
    if (!seen.has(key)) {
      seen.add(key);
      result.push(trimmed);
    }
  }

  return result;
}

module.exports = normalizeLabels;
